"""Parche T-008 E9: pantallas de Impulso Operativo (18 a 20), portada sin \u00abexcelencia\u00bb, pedido 2 y ?v=1.3.
Idempotente: verifica el SHA de partida y la cantidad exacta de cada reemplazo."""
import hashlib, pathlib, sys

INFORME = pathlib.Path('.github/parches/resultado-impulso-e9.md')
RUTA = pathlib.Path('index.html')
ANTES = '5f4a656e8d937e534fee5ee9c111b391a8f4177d'
REPS = [('<link rel="stylesheet" href="css/estilos.css?v=1.2">', '<link rel="stylesheet" href="css/estilos.css?v=1.3">\n<link rel="stylesheet" href="css/impulso.css?v=1.3">', 1), ('<script src="js/iconos.js?v=1.2"></script>', '<script src="js/iconos.js?v=1.3"></script>', 1), ('<script src="js/datos.js?v=1.2"></script>', '<script src="js/datos.js?v=1.3"></script>', 1), ('<script src="js/presentacion.js?v=1.2"></script>', '<script src="js/presentacion.js?v=1.3"></script>', 1), ('<p class="bajada">Reconstruyendo una operación diseñada para ser referente de eficiencia, fluidez y excelencia operacional.</p>', '<p class="bajada">Una operación que busca, todos los días, más eficiencia y más fluidez.</p>', 1), ('<!-- 18 -->\n<section class="pantalla cierre" id="conclusion"', '<!-- 18 -->\n<section class="pantalla" id="impulso" data-titulo="Impulso Operativo">\n  <div class="contenido">\n    <p class="sobretitulo revelar">El equipo</p>\n    <h2 class="revelar">Impulso Operativo</h2>\n    <p class="objetivo revelar"><i data-i="rayo"></i>Potenciamos la operación, desde el piso y en equipo.</p>\n    <p class="bajada revelar">La capacidad dedicada tiene nombre. Es el equipo que detecta mejoras con datos precisos y las lleva al piso junto con la operación, priorizando siempre lo que más impacto tiene en el servicio.</p>\n    <div class="esno">\n      <article class="tarjeta es revelar">\n        <h3>Lo que es</h3>\n        <ul>\n          <li><i data-i="check"></i>Un equipo que comparte el espacio operativo y trabaja en el campo.</li>\n          <li><i data-i="check"></i>Profesionalismo y precisión en la medición de los indicadores.</li>\n          <li><i data-i="check"></i>Prioridad por impacto: servicio, indicadores, tiempos y flujos.</li>\n          <li><i data-i="check"></i>Planes construidos con la operación y acompañados hasta el resultado.</li>\n          <li><i data-i="check"></i>Velocidad para actuar cuando hay que actuar.</li>\n        </ul>\n      </article>\n      <article class="tarjeta tarjeta-gris no revelar">\n        <h3>Lo que no es</h3>\n        <ul>\n          <li><i data-i="cerrar"></i>Un análisis desde el balcón.</li>\n          <li><i data-i="cerrar"></i>Una línea de mando: no da órdenes en la operación.</li>\n          <li><i data-i="cerrar"></i>Un área lenta que solo analiza.</li>\n          <li><i data-i="cerrar"></i>Alguien que impone soluciones.</li>\n        </ul>\n      </article>\n    </div>\n    <blockquote class="frase revelar">No venimos a decir qué está mal. Venimos a potenciar lo que la operación ya hace bien y a mejorar juntos lo que falta.</blockquote>\n  </div>\n</section>\n\n<!-- 19 -->\n<section class="pantalla" id="impulso-como" data-titulo="Impulso · Cómo trabaja">\n  <div class="contenido">\n    <p class="sobretitulo revelar">Cómo trabaja</p>\n    <h2 class="revelar">Del dato al piso, y del piso al resultado</h2>\n    <ol class="ruta revelar" aria-label="Ciclo de trabajo de Impulso Operativo">\n      <li><i data-i="lupa"></i><strong>Detectar</strong><span>en los indicadores y en el campo</span></li>\n      <li><i data-i="datos"></i><strong>Priorizar</strong><span>por impacto en el servicio</span></li>\n      <li><i data-i="personas"></i><strong>Construir el plan</strong><span>con jefes y supervisores</span></li>\n      <li><i data-i="rayo"></i><strong>Ejecutar</strong><span>en el piso, junto a la operación</span></li>\n      <li class="fin"><i data-i="indicador"></i><strong>Medir</strong><span>y sostener el resultado</span></li>\n    </ol>\n    <div class="dos-col impulso-col">\n      <div class="revelar">\n        <h3>Dónde pone el foco</h3>\n        <ul class="lista-items">\n          <li><i data-i="objetivo"></i>Calidad del servicio</li>\n          <li><i data-i="indicador"></i>Indicadores</li>\n          <li><i data-i="reloj"></i>Tiempos</li>\n          <li><i data-i="flujo"></i>Flujos de proceso</li>\n        </ul>\n        <p class="impulso-rol">Funciona como un <strong>gabinete operativo de la Gerencia de Procesamiento</strong>: lleva su visión al piso y trae la realidad del piso a la gerencia. No da órdenes en la operación: facilita el día a día de la gerencia de CIT, sus jefes y sus supervisores, y refuerza su liderazgo desde la colaboración.</p>\n      </div>\n      <figure class="organi revelar" aria-label="Ubicación en la organización: Impulso Operativo reporta a la Gerencia de Procesamiento y trabaja a la par de la gerencia de CIT">\n        <div class="org-caja org-top">Gerencia de Procesamiento<small>CIT · Planta Pacheco · Planta Avellaneda</small></div>\n        <div class="org-ramas">\n          <div class="org-col">\n            <div class="org-caja org-impulso">Impulso Operativo<small>reporte directo · analistas propios</small></div>\n          </div>\n          <div class="org-col">\n            <div class="org-caja">Gerencia de CIT</div>\n            <div class="org-caja org-sub">Jefes de turno</div>\n            <div class="org-caja org-sub">Supervisores</div>\n            <div class="org-caja org-sub">Operarios</div>\n          </div>\n        </div>\n        <figcaption>Trabaja a la par de la gerencia de CIT: colabora, acompaña y ejecuta en conjunto.</figcaption>\n      </figure>\n    </div>\n  </div>\n</section>\n\n<!-- 20 -->\n<section class="pantalla" id="impulso-equipo" data-titulo="Impulso · El equipo">\n  <div class="contenido">\n    <p class="sobretitulo revelar">Dimensión del equipo</p>\n    <h2 class="revelar">Un equipo chico, presente en cada turno</h2>\n    <p class="bajada revelar">Arrancamos en CIT, el primer foco. Cuidamos el gasto: el equipo crece solo cuando los resultados lo justifican.</p>\n    <div class="equipo">\n      <article class="tarjeta revelar"><p class="num">1</p><h3>Responsable de Impulso Operativo</h3><p>Prioriza la cartera de mejoras, sostiene el tablero de indicadores y el vínculo con la Gerencia de Procesamiento y la gerencia de CIT.</p></article>\n      <article class="tarjeta revelar"><p class="num">3</p><h3>Analistas de campo</h3><p>Uno por turno. Acompaña a los jefes de su turno, mide sus indicadores y lleva adelante las iniciativas en el piso.</p></article>\n    </div>\n    <ol class="horizontes fases">\n      <li class="horizonte revelar"><span class="dias">Arranque</span><h3>CIT</h3>\n        <ul><li>Tablero de indicadores confiable</li><li>Primeras mejoras de alto impacto</li><li>Presencia en los tres turnos</li></ul></li>\n      <li class="horizonte revelar"><span class="dias">Consolidación</span><h3>CIT</h3>\n        <ul><li>Rituales de seguimiento en marcha</li><li>Beneficios medidos y sostenidos</li><li>Mismo equipo, más resultados</li></ul></li>\n      <li class="horizonte revelar"><span class="dias">Expansión</span><h3>Otras plantas</h3>\n        <ul><li>Planta Pacheco y Planta Avellaneda</li><li>Un analista por planta</li><li>Solo con los resultados de CIT validados</li></ul></li>\n    </ol>\n    <blockquote class="frase revelar">Crecer con resultados, no con estructura.</blockquote>\n    <p class="nota revelar">Propuesta: los analistas pueden surgir de la propia operación. Conocen el piso y aceleran la adopción de las mejoras.</p>\n  </div>\n</section>\n\n<!-- 21 -->\n<section class="pantalla cierre" id="conclusion"', 1), ('<span>2</span>Habilitar la capacidad dedicada de transformación.', '<span>2</span>Habilitar Impulso Operativo, la capacidad dedicada de transformación.', 1), ('1 / 18', '1 / 21', 2)]


def sha(b):
    return hashlib.sha1(b'blob %d\x00' % len(b) + b).hexdigest()


def fin(estado, txt):
    INFORME.write_text('# Parche impulso E9\n\n- Resultado: ' + estado + '\n- ' + txt + '\n', encoding='utf-8')
    sys.exit(0 if estado == 'OK' else 1)


b = RUTA.read_bytes()
t = b.decode('utf-8')
if sha(b) != ANTES:
    if 'id="impulso"' in t:
        fin('OK', 'index.html: ya aplicado (' + sha(b)[:7] + ')')
    fin('FALLO', 'index.html: SHA inicial inesperado ' + sha(b))
for a, c, n in REPS:
    if t.count(a) != n:
        fin('FALLO', 'texto encontrado ' + str(t.count(a)) + ' veces (esperado ' + str(n) + '): ' + a[:80])
    t = t.replace(a, c)
nb = t.encode('utf-8')
RUTA.write_bytes(nb)
fin('OK', 'index.html: ' + ANTES[:7] + ' -> ' + sha(nb) + ' (' + str(len(nb)) + ' bytes, ' + str(t.count('class="pantalla')) + ' pantallas)')
